package commands

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// marker is the line goro puts before the package clause of every file it owns and regenerates
// (ADR 0001).
const marker = "// Code generated by goro. DO NOT EDIT."

// markerLine matches any line that counts as the marker, including the older
// "// Code generated by goro; DO NOT EDIT." header.
var markerLine = regexp.MustCompile(`^// Code generated by goro\b.*DO NOT EDIT\.$`)

// hasMarker reports whether a marker line comes before the package clause.
func hasMarker(content []byte) bool {
	for _, line := range strings.Split(string(content), "\n") {
		line = strings.TrimSuffix(line, "\r")
		if strings.HasPrefix(line, "package ") {
			return false
		}
		if markerLine.MatchString(line) {
			return true
		}
	}

	return false
}

// isGoroProject reports whether workDir already holds a goro project: a Go file in internal/app
// carries the marker. A directory that holds only goro.yaml, or code that goro didn't make, isn't
// one.
func isGoroProject(workDir string) (bool, error) {
	appDir := filepath.Join(workDir, "internal", "app")
	entries, err := os.ReadDir(appDir)
	if os.IsNotExist(err) {
		return false, nil
	}
	if err != nil {
		return false, err
	}

	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
			continue
		}
		content, err := os.ReadFile(filepath.Join(appDir, e.Name()))
		if err != nil {
			return false, err
		}
		if hasMarker(content) {
			return true, nil
		}
	}

	return false, nil
}
